<?php
namespace App\Http\Controllers; use App\Http\Requests\{GradeTrainingEvaluationAnswerRequest,StoreTrainingEvaluationRequest}; use App\Models\{TrainingEvaluation,TrainingEvaluationAnswer,TrainingQuestion,TrainingSession,TrainingTopic}; use App\Services\{TrainingEvaluationScoringService,TrainingEvaluationService}; use Illuminate\Http\Request;
class TrainingEvaluationController extends Controller{public function index(){ $evaluations=TrainingEvaluation::forCompany(auth()->user()->company_id)->with(['session','topic'])->latest()->get();return view('training.evaluations.index',compact('evaluations'));}public function store(StoreTrainingEvaluationRequest$r,TrainingEvaluationService$s){$e=$s->create($r->validated(),$r->user()->company_id,$r->user()->id);return redirect()->route('training.evaluations.show',$e);}public function show(TrainingEvaluation$evaluation){$this->own($evaluation);$evaluation->load(['session.attendanceEvent.participants','topic','questions.options','attempts.participant','attempts.answers.evaluationQuestion']);$bank=TrainingQuestion::forCompany($evaluation->company_id)->where('training_topic_id',$evaluation->training_topic_id)->where('is_active',true)->with('options')->get();return view('training.evaluations.show',compact('evaluation','bank'));}public function publish(TrainingEvaluation$evaluation,Request$r,TrainingEvaluationService$s){$this->own($evaluation);$d=$r->validate(['question_ids'=>'required|array|min:1','question_ids.*'=>'exists:training_questions,id']);$links=$s->publish($evaluation,$d['question_ids'],$r->user()->id);return back()->with(['success'=>'Evaluación publicada y versión congelada.','evaluation_links'=>$links]);}public function gradeAnswer(TrainingEvaluation$evaluation,TrainingEvaluationAnswer$answer,GradeTrainingEvaluationAnswerRequest$r,TrainingEvaluationService$s,TrainingEvaluationScoringService$scoring){$this->own($evaluation);abort_unless($answer->attempt->training_evaluation_id===$evaluation->id,404);$d=$r->validated();$s->gradeAnswer($answer,(bool)$d['is_correct'],$d['evaluator_observations']??null,$r->user()->id,$scoring);return back()->with('success','Respuesta calificada.');}private function own($e){abort_unless((int)$e->company_id===(int)auth()->user()->company_id,403);}}
